SysDataModelXML.SQLUpdateScript:
--LINKJSONDATASUBMIT --UPDATE PREQAL SET PRQNUM='#DOCNUM#',PRQQTY=0#PRQQTY#,PRQQTYSTU=0#PRQQTY#*0#UOMCOE# --WHERE DOCNUM='#SRCDOC#'AND DOCLIN=0#SRCLIN# AND '#GXFLG#'='1';
DECLARE @json NVARCHAR(MAX); SET @json = N'#LINKJSON{$.formData}#'; DECLARE @TABLE_1 NVARCHAR(MAX); SET @TABLE_1 = N'#LINKJSON{$.TABLE_1}#';
MERGE INTO PREQAL D USING ( SELECT GXFLG,PRQNUM,DOCNUM,DOCLIN,PRQQTY,UOMCOE FROM OPENJSON(@TABLE_1) WITH ( GXFLG varchar(1) '$.GXFLG', -- 新增 GXFLG 字段 PRQNUM varchar(30) '$.DOCNUM', DOCNUM varchar(30) '$.SRCDOC', DOCLIN int '$.SRCLIN', PRQQTY decimal(18, 6) '$.PRQQTY', UOMCOE decimal(18, 6) '$.UOMCOE' ) WHERE GXFLG = '1' -- 筛选 GXFLG 为 "1" 的记录 ) S ON D.DOCNUM = S.DOCNUM AND D.DOCLIN = S.DOCLIN WHEN MATCHED THEN UPDATE SET PRQNUM = S.PRQNUM, PRQQTY = S.PRQQTY, PRQQTYSTU = S.PRQQTY * S.UOMCOE;
